import React, { useState, useEffect } from 'react';
import { FaExchangeAlt, FaInfoCircle } from 'react-icons/fa';
import { useTheme } from '../context/ThemeContext';

const CurrencyExchange = ({ budget, onExchangeRateChange }) => {
  const { theme } = useTheme();
  const [showTooltip, setShowTooltip] = useState(false);
  const [fromCurrency, setFromCurrency] = useState('USD');
  const [toCurrency, setToCurrency] = useState('EUR');
  const [exchangeRate, setExchangeRate] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState(null);

  // Common currencies with their symbols
  const currencies = {
    USD: { symbol: '$', name: 'US Dollar' },
    EUR: { symbol: '€', name: 'Euro' },
    GBP: { symbol: '£', name: 'British Pound' },
    JPY: { symbol: '¥', name: 'Japanese Yen' },
    AUD: { symbol: 'A$', name: 'Australian Dollar' },
    CAD: { symbol: 'C$', name: 'Canadian Dollar' },
    CHF: { symbol: 'Fr', name: 'Swiss Franc' },
    CNY: { symbol: '¥', name: 'Chinese Yuan' },
    INR: { symbol: '₹', name: 'Indian Rupee' },
    SGD: { symbol: 'S$', name: 'Singapore Dollar' }
  };

  useEffect(() => {
    if (fromCurrency && toCurrency) {
      fetchExchangeRate();
    }
  }, [fromCurrency, toCurrency]);

  const fetchExchangeRate = async () => {
    setIsLoading(true);
    setError(null);
    try {
      const response = await fetch(`https://open.er-api.com/v6/latest/${fromCurrency}`);
      const data = await response.json();
      
      if (data.result === 'success') {
        const rate = data.rates[toCurrency];
        setExchangeRate(rate);
        onExchangeRateChange(rate);
      } else {
        throw new Error('Failed to fetch exchange rate');
      }
    } catch (err) {
      setError('Unable to fetch exchange rate');
      console.error('Exchange rate error:', err);
    } finally {
      setIsLoading(false);
    }
  };

  const formatAmount = (amount, currency) => {
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: currency,
      minimumFractionDigits: 2,
      maximumFractionDigits: 2
    }).format(amount);
  };

  const handleSwapCurrencies = () => {
    setFromCurrency(toCurrency);
    setToCurrency(fromCurrency);
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center space-x-2">
        <h3 className="text-lg font-medium" style={{ color: theme.text }}>
          Currency Exchange
        </h3>
        <div className="relative">
          <button
            onMouseEnter={() => setShowTooltip(true)}
            onMouseLeave={() => setShowTooltip(false)}
            className="focus:outline-none"
            style={{ color: theme.textLight }}
          >
            <FaInfoCircle className="text-lg" />
          </button>
          
          {showTooltip && (
            <div 
              className="absolute z-10 w-72 p-4 rounded-lg shadow-lg transform -translate-x-1/2 left-1/2 mt-2"
              style={{ 
                backgroundColor: theme.background,
                border: `1px solid ${theme.border}`,
                color: theme.text
              }}
            >
              <p className="text-sm leading-relaxed">
                Real-time currency conversion using live exchange rates. Your budget will be automatically converted to help you plan your expenses in the local currency.
              </p>
              <div 
                className="absolute w-3 h-3 transform rotate-45 -top-2 left-1/2 -translate-x-1/2"
                style={{ backgroundColor: theme.background, borderLeft: `1px solid ${theme.border}`, borderTop: `1px solid ${theme.border}` }}
              />
            </div>
          )}
        </div>
      </div>

      <div className="space-y-4">
        {/* Currency Selection */}
        <div className="flex items-center space-x-4">
          <select
            value={fromCurrency}
            onChange={(e) => setFromCurrency(e.target.value)}
            className="flex-1 p-2 rounded-lg focus:outline-none focus:ring-2 focus:ring-opacity-50 transition-colors"
            style={{ 
              borderColor: theme.border,
              backgroundColor: theme.background,
              color: theme.text
            }}
          >
            {Object.entries(currencies).map(([code, { symbol, name }]) => (
              <option key={code} value={code}>
                {code} ({symbol}) - {name}
              </option>
            ))}
          </select>

          <button
            onClick={handleSwapCurrencies}
            className="p-2 rounded-full hover:bg-opacity-10 transition-colors"
            style={{ 
              backgroundColor: `${theme.primary}20`,
              color: theme.primary
            }}
          >
            <FaExchangeAlt className="text-xl" />
          </button>

          <select
            value={toCurrency}
            onChange={(e) => setToCurrency(e.target.value)}
            className="flex-1 p-2 rounded-lg focus:outline-none focus:ring-2 focus:ring-opacity-50 transition-colors"
            style={{ 
              borderColor: theme.border,
              backgroundColor: theme.background,
              color: theme.text
            }}
          >
            {Object.entries(currencies).map(([code, { symbol, name }]) => (
              <option key={code} value={code}>
                {code} ({symbol}) - {name}
              </option>
            ))}
          </select>
        </div>

        {/* Exchange Rate Display */}
        {isLoading ? (
          <div className="text-center py-4" style={{ color: theme.textLight }}>
            Updating exchange rate...
          </div>
        ) : error ? (
          <div className="text-center py-4" style={{ color: theme.primary }}>
            {error}
          </div>
        ) : exchangeRate && (
          <div className="p-4 rounded-lg" style={{ backgroundColor: theme.background }}>
            <div className="space-y-2">
              <div className="flex justify-between items-center">
                <span style={{ color: theme.textLight }}>Exchange Rate</span>
                <span style={{ color: theme.text }}>1 {fromCurrency} = {exchangeRate.toFixed(4)} {toCurrency}</span>
              </div>
              {budget && (
                <div className="flex justify-between items-center">
                  <span style={{ color: theme.textLight }}>Converted Budget</span>
                  <span style={{ color: theme.text }}>
                    {formatAmount(budget * exchangeRate, toCurrency)}
                  </span>
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default CurrencyExchange;
